    let graph = Graph::import(
        &from_indoc(indoc! {"
            title: Foo
            depends:
              - foo
              - bar

            # Body
            "}),
        bare_options(),
        None,
    );

    let raw = graph.get_metadata(&"".into()).expect("metadata present");
    let val: serde_yaml::Value = serde_yaml::from_str(raw).expect("valid yaml");
    let deps = val.get("depends").and_then(|v| v.as_sequence()).expect("depends list");
    let items: Vec<&str> = deps.iter().filter_map(|v| v.as_str()).collect();
    assert_eq!(items, vec!["foo", "bar"]);
}

